class Solution {
  public int sortableIntegers(int[] nums) {
    int n = nums.length, total = 0;
    for (int k = 1; k <= n; k++) {
      if (n % k != 0) continue;
      boolean ok = true;
      int prevMax = Integer.MIN_VALUE;
      for (int start = 0; start < n && ok; start += k) {
        int descents = 0, mn = Integer.MAX_VALUE, mx = Integer.MIN_VALUE;
        for (int j = 0; j < k; j++) {
          int cur = nums[start + j], next = nums[start + (j + 1) % k];
          if (cur > next) descents++;
          mn = Math.min(mn, cur);
          mx = Math.max(mx, cur);
        }
        if (descents > 1 || mn < prevMax) ok = false;
        prevMax = mx;
      }
      if (ok) total += k;
    }
    return total;
  }
}
